// Generated by esquadro: do not edit. A list's filters: one editor for each
// kind of field (an enum's values with their dots, yes or no, a related
// record, a range of money, a period), the same in each place they are
// shown: a drawer or a dialog (a draft, applied at once), a bar beside the
// search, a column's header. The filters are the API's (@store(filter)),
// and live in the URL.
import { useQuery } from "@tanstack/react-query"
import { Check, ChevronsUpDown, Filter, ListFilter as ListFilterIcon, Minus, X } from "lucide-react"
import { Fragment, useEffect, useState } from "react"
import type { ReactNode } from "react"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Separator } from "@/components/ui/separator"
import { Sheet, SheetContent, SheetDescription, SheetFooter, SheetHeader, SheetTitle } from "@/components/ui/sheet"
import { cn } from "@/lib/utils"
import { api } from "../api.ts"
import { resources } from "../resources.gen.ts"
import { DateRangeFilter, periodSummary } from "./daterange.tsx"
import { capitalize, format, t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"
import { formatMoney, MoneyInput } from "./money.tsx"
import type { Money } from "./money.tsx"
import { MoneyRangeFilter } from "./moneyrange.tsx"
import { StatusDot } from "./status.tsx"

/** The filters' values, by their keys in the URL (status, price_min). */
export type FilterValues = Record<string, string | undefined>

/** Where a list's filters are: a drawer, a dialog, or a bar beside the search. */
export type FilterLayout = "drawer" | "dialog" | "bar"

const ALL = "__all"

/** A button in a panel that looks like the form's fields: filled, no border. */
export const fieldLook =
  "h-11 w-full rounded-lg border-transparent bg-input px-3 font-semibold shadow-none hover:bg-input/80 focus-visible:border-ring focus-visible:ring-1 focus-visible:ring-ring dark:bg-input dark:hover:bg-input/80"

/** A filter by a date: a period, in two params (created_at_min, _max). */
export function isDateField(f: FieldMeta): boolean {
  return f.kind === "date" || f.kind === "datetime"
}

/** The URL's keys of a filter: a range's two (price_min, price_max). */
export function filterKeys(f: FieldMeta): string[] {
  return isDateField(f) || f.kind === "money" ? [`${f.name}_min`, `${f.name}_max`] : [f.name]
}

/** Whether a filter is set. */
export function isActive(f: FieldMeta, values: FilterValues): boolean {
  return filterKeys(f).some((k) => values[k] !== undefined && values[k] !== "")
}

/** Each key of a filter, unset. */
export function cleared(fields: FieldMeta[]): FilterValues {
  return Object.fromEntries(fields.flatMap(filterKeys).map((k) => [k, undefined]))
}

/** An enum's values (several, in the URL as A,B). */
function chosen(value?: string): string[] {
  return value ? value.split(",").filter(Boolean) : []
}

/** The records a relation may point at, fetched once and cached. */
function useRelated(field: FieldMeta) {
  const target = (resources as unknown as Record<string, ResourceMeta>)[field.target ?? ""]
  const related = useQuery({
    queryKey: [target?.name ?? field.target, "options"],
    queryFn: ({ signal }) => target.api(api as never).list({ per_page: 100, limit: 100 }, { signal }),
    enabled: field.kind === "relation" && target !== undefined,
    staleTime: 60_000,
  })
  const options: [string, string][] = (related.data?.items ?? []).map((r: Rec) => [r.id, capitalize(String(r[field.display ?? "id"] ?? r.id))])
  return options
}

/** What a filter reads, in a chip: "Active, Draft", "R$ 10 – R$ 50", "Last 7 days". */
function useSummary(field: FieldMeta, values: FilterValues): string {
  const related = useRelated(field)
  const v = values[field.name]
  if (field.kind === "money") {
    const min = values[`${field.name}_min`]
    const max = values[`${field.name}_max`]
    const m = (a: string) => formatMoney({ amount: a })
    return min && max ? `${m(min)} – ${m(max)}` : min ? `${t("from")} ${m(min)}` : max ? `${t("upTo")} ${m(max)}` : t("all")
  }
  if (isDateField(field)) return periodSummary(values[`${field.name}_min`], values[`${field.name}_max`])
  if (field.kind === "relation") return related.find(([id]) => id === v)?.[1] ?? "…"
  if (field.kind === "bool") return capitalize(format(field, v === "true"))
  return chosen(v)
    .map((x) => capitalize(format(field, x)))
    .join(", ")
}

/** An enum's values to check, each with its dot: several at once. */
function EnumChecks({ field, value, onChange }: { field: FieldMeta; value?: string; onChange: (v?: string) => void }) {
  const on = chosen(value)
  return (
    <div className="flex flex-col gap-1">
      {(field.values ?? []).map((v) => {
        const id = `filter-${field.name}-${v}`
        return (
          <label
            key={v}
            htmlFor={id}
            className="flex h-10 cursor-pointer items-center justify-between gap-3 rounded-lg px-2 text-sm font-semibold text-foreground hover:bg-muted"
          >
            <span className="flex items-center gap-2.5">
              <StatusDot field={field} value={v} />
              {capitalize(format(field, v))}
            </span>
            <Checkbox
              id={id}
              checked={on.includes(v)}
              onCheckedChange={(c) => {
                const next = c ? [...on, v] : on.filter((x) => x !== v)
                // In the enum's order, as people read the list.
                const ordered = (field.values ?? []).filter((x) => next.includes(x))
                onChange(ordered.length ? ordered.join(",") : undefined)
              }}
            />
          </label>
        )
      })}
    </div>
  )
}

/** Yes, no, or either: three buttons side by side. */
function BoolChoice({ field, value, onChange }: { field: FieldMeta; value?: string; onChange: (v?: string) => void }) {
  const options: [string | undefined, string][] = [
    [undefined, capitalize(t("all"))],
    ["true", capitalize(format(field, true))],
    ["false", capitalize(format(field, false))],
  ]
  return (
    <div role="radiogroup" aria-label={field.label} className="grid grid-cols-3 gap-1 rounded-lg bg-muted p-1">
      {options.map(([v, label]) => (
        <button
          key={label}
          type="button"
          role="radio"
          aria-checked={value === v}
          onClick={() => onChange(v)}
          className={cn(
            "h-9 rounded-md text-sm font-semibold text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
            value === v && "bg-card text-foreground shadow-sm",
          )}
        >
          {label}
        </button>
      ))}
    </div>
  )
}

/** A related record, searched by what it is called. */
function RelationPick({ field, value, onChange }: { field: FieldMeta; value?: string; onChange: (v?: string) => void }) {
  const [open, setOpen] = useState(false)
  const options = useRelated(field)
  const current = options.find(([id]) => id === value)
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          id={`filter-${field.name}`}
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className={cn(fieldLook, "justify-between", !current && "text-muted-foreground")}
        >
          <span className="truncate">{current?.[1] ?? capitalize(t("all"))}</span>
          <ChevronsUpDown className="opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-(--radix-popover-trigger-width) p-0" align="start">
        <Command>
          <CommandInput placeholder={t("searchIn", { name: field.label.toLocaleLowerCase() })} />
          <CommandList>
            <CommandEmpty>{t("nothingHere")}</CommandEmpty>
            <CommandGroup>
              <CommandItem
                value={`__all ${t("all")}`}
                onSelect={() => {
                  onChange(undefined)
                  setOpen(false)
                }}
              >
                <Check className={cn(value === undefined ? "opacity-100" : "opacity-0")} />
                {capitalize(t("all"))}
              </CommandItem>
              {options.map(([id, label]) => (
                <CommandItem
                  key={id}
                  value={`${label} ${id}`}
                  onSelect={() => {
                    onChange(id)
                    setOpen(false)
                  }}
                >
                  <Check className={cn(value === id ? "opacity-100" : "opacity-0")} />
                  {label}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

/** From an amount up to another, with the currency's symbol. */
function MoneyRange({ field, min, max, onChange }: { field: FieldMeta; min?: string; max?: string; onChange: (min?: string, max?: string) => void }) {
  const negative = field.min === undefined || field.min < 0
  return (
    <div className="grid grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-2">
      <MoneyInput
        id={`filter-${field.name}`}
        aria-label={`${field.label}: ${t("from")}`}
        placeholder={capitalize(t("from"))}
        value={min ? ({ amount: min } as Money) : null}
        onChange={(m) => onChange(m?.amount, max)}
        negative={negative}
        className="h-11 w-full"
      />
      <Minus className="size-4 text-muted-foreground" />
      <MoneyInput
        aria-label={`${field.label}: ${t("upTo")}`}
        placeholder={capitalize(t("upTo"))}
        value={max ? ({ amount: max } as Money) : null}
        onChange={(m) => onChange(min, m?.amount)}
        negative={negative}
        className="h-11 w-full"
      />
    </div>
  )
}

/** A filter's editor, in a panel (a drawer, a dialog, a column's popover). */
export function FieldFilter({ field, values, onChange }: { field: FieldMeta; values: FilterValues; onChange: (changes: FilterValues) => void }) {
  const min = values[`${field.name}_min`]
  const max = values[`${field.name}_max`]
  const range = (a?: string, b?: string) => onChange({ [`${field.name}_min`]: a, [`${field.name}_max`]: b })
  const one = (v?: string) => onChange({ [field.name]: v })
  if (field.kind === "money") return <MoneyRange field={field} min={min} max={max} onChange={range} />
  if (isDateField(field)) return <DateRangeFilter bare field={field} min={min} max={max} onChange={range} />
  if (field.kind === "relation") return <RelationPick field={field} value={values[field.name]} onChange={one} />
  if (field.kind === "bool") return <BoolChoice field={field} value={values[field.name]} onChange={one} />
  return <EnumChecks field={field} value={values[field.name]} onChange={one} />
}

/** Every filter, each under its name, one under the other. */
function FilterFields({ filters, values, onChange }: { filters: FieldMeta[]; values: FilterValues; onChange: (changes: FilterValues) => void }) {
  return (
    <div className="flex flex-col gap-6">
      {filters.map((f, i) => (
        <Fragment key={f.name}>
          {i > 0 && <Separator />}
          <div className="flex flex-col gap-3">
            <Label htmlFor={`filter-${f.name}`} className="text-sm font-bold text-foreground">
              {f.label}
            </Label>
            <FieldFilter field={f} values={values} onChange={onChange} />
          </div>
        </Fragment>
      ))}
    </div>
  )
}

/**
 * The Filters button and its drawer (or dialog): the filters changed in a
 * draft, applied at once; closing it gives the draft up.
 */
export function FilterPanel({
  filters,
  values,
  onApply,
  layout,
  open,
  onOpenChange,
}: {
  filters: FieldMeta[]
  values: FilterValues
  onApply: (changes: FilterValues) => void
  layout: "drawer" | "dialog"
  open: boolean
  onOpenChange: (open: boolean) => void
}) {
  const [draft, setDraft] = useState<FilterValues>({})
  const active = filters.filter((f) => isActive(f, values)).length
  // Opened from its button or from a chip, it starts from what is applied.
  useEffect(() => {
    if (open) setDraft(Object.fromEntries(filters.flatMap(filterKeys).map((k) => [k, values[k]])))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open])
  const show = onOpenChange
  const change = (changes: FilterValues) => setDraft((d) => ({ ...d, ...changes }))
  const apply = () => {
    onApply(draft)
    onOpenChange(false)
  }
  const fields = <FilterFields filters={filters} values={draft} onChange={change} />
  const buttons = (
    <>
      <Button variant="outline" onClick={() => setDraft(cleared(filters))}>
        {t("clearFilters")}
      </Button>
      <Button onClick={apply}>{t("apply")}</Button>
    </>
  )
  const trigger = (
    <Button variant="outline" className={cn(active > 0 && "border-primary text-primary")} onClick={() => show(true)} aria-haspopup="dialog">
      <ListFilterIcon /> {t("filters")}
      {active > 0 && <span className="rounded-md bg-primary px-1.5 text-xs text-primary-foreground">{active}</span>}
    </Button>
  )
  if (layout === "dialog") {
    return (
      <>
        {trigger}
        <Dialog open={open} onOpenChange={show}>
          <DialogContent className="gap-0 overflow-hidden p-0 sm:max-w-lg">
            <DialogHeader className="border-b border-border px-6 py-4">
              <DialogTitle className="text-lg font-bold">{t("filters")}</DialogTitle>
              <DialogDescription className="sr-only">{t("filters")}</DialogDescription>
            </DialogHeader>
            <div className="max-h-[65svh] overflow-y-auto px-6 py-5">{fields}</div>
            <DialogFooter className="border-t border-border bg-muted px-6 py-3">{buttons}</DialogFooter>
          </DialogContent>
        </Dialog>
      </>
    )
  }
  return (
    <>
      {trigger}
      <Sheet open={open} onOpenChange={show}>
        <SheetContent side="right" className="w-full gap-0 sm:max-w-[400px]">
          <SheetHeader className="border-b border-border px-6 py-4">
            <SheetTitle className="text-lg font-bold">{t("filters")}</SheetTitle>
            <SheetDescription className="sr-only">{t("filters")}</SheetDescription>
          </SheetHeader>
          <div className="flex-1 overflow-y-auto px-6 py-5">{fields}</div>
          <SheetFooter className="grid grid-cols-2 gap-2 border-t border-border px-6 py-4">{buttons}</SheetFooter>
        </SheetContent>
      </Sheet>
    </>
  )
}

/** A filter beside the search: a choice, a range's or a period's popover, applied at once. */
export function BarFilter({ field, values, onChange }: { field: FieldMeta; values: FilterValues; onChange: (changes: FilterValues) => void }) {
  const range = (a?: string, b?: string) => onChange({ [`${field.name}_min`]: a, [`${field.name}_max`]: b })
  if (field.kind === "money") {
    return <MoneyRangeFilter field={field} min={values[`${field.name}_min`]} max={values[`${field.name}_max`]} onChange={range} />
  }
  if (isDateField(field)) {
    return <DateRangeFilter field={field} min={values[`${field.name}_min`]} max={values[`${field.name}_max`]} onChange={range} />
  }
  return <BarChoice field={field} value={values[field.name]} onChange={(v) => onChange({ [field.name]: v })} />
}

/** An enum's value (with its dot), yes or no, or a related record: one. */
function BarChoice({ field, value, onChange }: { field: FieldMeta; value?: string; onChange: (v?: string) => void }) {
  const related = useRelated(field)
  const options: [string, string][] =
    field.kind === "relation"
      ? related
      : (field.values ?? ["true", "false"]).map((v) => [v, capitalize(field.kind === "bool" ? format(field, v === "true") : format(field, v))])
  // Of an enum's values, the bar keeps one: the first, when the URL has several.
  const one = chosen(value)[0]
  return (
    <Select value={one ?? ALL} onValueChange={(v) => onChange(v === ALL ? undefined : v)}>
      <SelectTrigger className={cn("w-auto min-w-40 font-semibold", one && "border-primary")}>
        <span className="font-medium text-muted-foreground">{field.label}:</span>
        <SelectValue />
      </SelectTrigger>
      <SelectContent position="popper">
        <SelectItem value={ALL}>{capitalize(t("all"))}</SelectItem>
        {options.map(([v, label]) => (
          <SelectItem key={v} value={v}>
            {field.kind === "enum" && <StatusDot field={field} value={v} />}
            {label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

/** A set filter's chip: its name and what it keeps; X takes it off. */
function Chip({ field, values, onChange, onOpen }: { field: FieldMeta; values: FilterValues; onChange: (changes: FilterValues) => void; onOpen?: () => void }) {
  const summary = useSummary(field, values)
  return (
    <span className="inline-flex h-8 items-center gap-1 rounded-full border border-primary/30 bg-primary/5 pr-1 pl-3 text-sm text-foreground">
      <button type="button" onClick={onOpen} className="flex items-center gap-1 font-semibold focus-visible:underline focus-visible:outline-none">
        <span className="font-medium text-muted-foreground">{field.label}:</span>
        <span className="max-w-60 truncate">{summary}</span>
      </button>
      <button
        type="button"
        aria-label={`${t("clearFilters")}: ${field.label}`}
        onClick={() => onChange(cleared([field]))}
        className="flex size-6 items-center justify-center rounded-full text-muted-foreground hover:bg-primary/10 hover:text-foreground"
      >
        <X className="size-3.5" />
      </button>
    </span>
  )
}

/** The filters set, as chips under the search, and Clear all. */
export function ActiveFilters({
  filters,
  values,
  onChange,
  onOpen,
  children,
}: {
  filters: FieldMeta[]
  values: FilterValues
  onChange: (changes: FilterValues) => void
  onOpen?: () => void
  /** After Clear all: Save filter. */
  children?: ReactNode
}) {
  const set = filters.filter((f) => isActive(f, values))
  if (set.length === 0) return null
  return (
    <div className="flex flex-wrap items-center gap-2 animate-in fade-in-0">
      {set.map((f) => (
        <Chip key={f.name} field={f} values={values} onChange={onChange} onOpen={onOpen} />
      ))}
      <Button variant="ghost" size="sm" className="text-muted-foreground" onClick={() => onChange(cleared(filters))}>
        {t("clearAll")}
      </Button>
      {children}
    </div>
  )
}

/**
 * A column's filter, in its header: a funnel (filled when set) opening the
 * field's editor, applied at once (a range or a period, on Apply).
 */
export function ColumnFilter({ field, values, onChange }: { field: FieldMeta; values: FilterValues; onChange: (changes: FilterValues) => void }) {
  const [open, setOpen] = useState(false)
  const [draft, setDraft] = useState<FilterValues>({})
  const active = isActive(field, values)
  const ranged = field.kind === "money"
  return (
    <Popover
      open={open}
      onOpenChange={(o) => {
        if (o) setDraft(Object.fromEntries(filterKeys(field).map((k) => [k, values[k]])))
        setOpen(o)
      }}
    >
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={`${t("filters")}: ${field.label}`}
          className={cn(
            "inline-flex size-6 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground",
            active && "text-primary hover:text-primary",
          )}
        >
          <Filter className={cn("size-3.5", active && "fill-current")} />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="flex w-72 flex-col gap-3 normal-case">
        <p className="text-sm font-bold tracking-normal text-foreground">{field.label}</p>
        <FieldFilter
          field={field}
          values={ranged ? draft : values}
          onChange={(c) => (ranged ? setDraft((d) => ({ ...d, ...c })) : onChange(c))}
        />
        {ranged && (
          <Button
            size="sm"
            onClick={() => {
              onChange(draft)
              setOpen(false)
            }}
          >
            {t("apply")}
          </Button>
        )}
        {active && (
          <Button variant="ghost" size="sm" className="text-muted-foreground" onClick={() => onChange(cleared([field]))}>
            <X /> {t("clearFilters")}
          </Button>
        )}
      </PopoverContent>
    </Popover>
  )
}

/**
 * Tabs above a list by an enum or a yes or no field: All, then each value,
 * with how many records each keeps (the API's total, by page; none by
 * cursor). Choosing one filters the list by it.
 */
export function FilterTabs({
  field,
  value,
  onChange,
  count,
}: {
  field: FieldMeta
  value?: string
  onChange: (v?: string) => void
  /** How many records a value keeps (undefined: all of them), or nothing to show none. */
  count?: (v?: string) => number | undefined
}) {
  const options: [string | undefined, string][] = [
    [undefined, capitalize(t("all"))],
    ...(field.values ?? ["true", "false"]).map((v): [string, string] => [v, capitalize(field.kind === "bool" ? format(field, v === "true") : format(field, v))]),
  ]
  const current = chosen(value)[0]
  return (
    <div role="tablist" aria-label={field.label} className="flex w-fit max-w-full gap-1 overflow-x-auto rounded-xl bg-muted p-1">
      {options.map(([v, label]) => {
        const n = count?.(v)
        const on = current === v
        return (
          <button
            key={label}
            type="button"
            role="tab"
            aria-selected={on}
            onClick={() => onChange(v)}
            className={cn(
              "flex h-9 shrink-0 items-center gap-2 rounded-lg px-3.5 text-sm font-semibold whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
              on && "bg-card text-foreground shadow-sm",
            )}
          >
            {v !== undefined && field.kind === "enum" && <StatusDot field={field} value={v} />}
            {label}
            {n !== undefined && (
              <span className={cn("rounded-full px-1.5 text-xs tabular-nums", on ? "bg-primary/10 text-primary" : "bg-background text-muted-foreground")}>{n}</span>
            )}
          </button>
        )
      })}
    </div>
  )
}
